            result["text.burst.log_median"] = math.log1p(median(bursts)) if bursts else 0.0
            result["text.burst.spread"] = _spread(bursts) if bursts else 0.0
            result["text.correction.fraction"] = mean(float(value) for value in corrections)
            total = sum(inserted + removed for inserted, removed in counts)
            result["text.correction.removed_fraction"] = sum(removed for _, removed in counts) / total
            correction_gaps, other_gaps = [], []
            for index in range(1, len(events)):
