# SPDX-License-Identifier: MIT
"""Offline behavioral comparison for Marrow event recordings, Python 3.10+.

Run `python marrow.py demo` for the deterministic synthetic evaluation.
Run `python marrow.py train model.json enrollment*.json --calibration calibration.json ...`
and `python marrow.py check model.json recording.json` for independent recordings.

Input is a JSON array in time order. Each event has a nonnegative integer
`ms` and a `kind`. `move` and `click` also have normalized `x` and `y` in [0,1].
`text` has `source` (typed, onscreen, inserted) and `action` (add, correct).
Do not include characters, keys, device IDs, audio, or personal identifiers.
One file is one session. A correction is an edit event regardless of its source.
"""

import argparse
import json
import math
import random
from pathlib import Path
from statistics import median

FLOORS = (0.025, 0.025, 0.015, 0.035, 0.045, 0.055, 0.05, 0.035)
FEATURES = (
    "click-distance-dispersion", "move-timing-dispersion", "path-inefficiency",
    "approach-braking", "edit-fraction", "edit-early-recovery",
    "text-timing-dispersion", "edit-followup-asymmetry",
)
MIN_CALIBRATION_MARGIN = 0.2


def read(path):
    return json.loads(Path(path).read_text(encoding="utf-8"))


def displacement(a, b):
    return math.hypot(a["x"] - b["x"], a["y"] - b["y"])


def dispersion(values):
    center = median(values)
    return median(abs(value - center) for value in values) / max(center, 1e-9)


def features(events):
    if not isinstance(events, list):
        raise ValueError("expected a JSON array of events")
    path, clicks, edits = [], [], []
    previous_ms = -1
    for event in events:
        if not isinstance(event, dict):
            raise ValueError("expected an event object")
        ms = event.get("ms")
        if type(ms) is not int or ms < max(0, previous_ms):
            raise ValueError("invalid or out-of-order timestamp")
        previous_ms = ms
        kind = event.get("kind")
        if kind in ("move", "click"):
            for axis in ("x", "y"):
                value = event.get(axis)
                if type(value) not in (int, float) or not 0 <= value <= 1:
                    raise ValueError("pointer positions must be normalized")
            if kind == "click":
                clicks.append((event, path))
                path = []
            else:
                path.append(event)
        elif kind == "text":
            if event.get("source") not in ("typed", "onscreen", "inserted"):
                raise ValueError("unknown text source")
            if event.get("action") not in ("add", "correct"):
                raise ValueError("unknown text action")
            edits.append(event)
        else:
            raise ValueError("unknown event kind")

    distances, movement_gaps, detours, braking = [], [], [], []
    for click, approach in clicks:
        if len(approach) < 4:
            continue
        approach = [*approach, click]
        steps = [displacement(a, b) for a, b in zip(approach, approach[1:])]
        total = sum(steps)
        if total <= 1e-8:
            continue
        distances.append(total)
        detours.append(1 - displacement(approach[0], click) / total)
        braking.append(sum(steps[-2:]) / total)
        movement_gaps.extend(b["ms"] - a["ms"] for a, b in zip(approach, approach[1:]))

    gaps = [b["ms"] - a["ms"] for a, b in zip(edits, edits[1:])]
    indices = [i for i in range(1, len(edits) - 1) if edits[i]["action"] == "correct"]
    if len(distances) < 8 or len(gaps) < 20 or median(gaps) == 0:
        raise ValueError("insufficient pointer or text evidence")
    if median(movement_gaps) == 0:
        raise ValueError("insufficient pointer timing evidence")
    text_scale = median(gaps)
    return (
        dispersion(distances), dispersion(movement_gaps), median(detours), median(braking),
        sum(event["action"] == "correct" for event in edits) / len(edits),
        median([gaps[i] < text_scale for i in indices]) if indices else 0.0,
        dispersion(gaps),
        median((gaps[i] - gaps[i - 1]) / max(1, gaps[i] + gaps[i - 1]) for i in indices)
        if indices else 0.0,
    )


def score(model, observation):
    errors = [min(8.0, abs(x - center) / scale)
              for x, center, scale in zip(observation, model["center"], model["scale"])]
    return max(math.sqrt(sum(x * x for x in group) / len(group))
               for group in (errors[:4], errors[4:]))


def train(enrollment, calibration):
    if len(enrollment) < 5 or len(calibration) < 3:
        raise ValueError("need five enrollment and three distinct calibration sessions")
    columns = list(zip(*(features(session) for session in enrollment)))
    center = [median(column) for column in columns]
    scale = [max(floor, 1.4826 * median(abs(x - mu) for x in column))
             for floor, mu, column in zip(FLOORS, center, columns)]
    model = {"schema": "marrow-model-v1", "features": FEATURES, "center": center, "scale": scale}
    model["threshold"] = max(score(model, features(session)) for session in calibration) + MIN_CALIBRATION_MARGIN
    return model


def check(model, events):
    try:
        distance = score(model, features(events))
    except ValueError as exc:
        return {"decision": "doubt", "reason": str(exc)}
