class FormatError(ValueError):
    """A recording violates the documented neutral format."""


def median(values: Iterable[float]) -> float:
    return float(statistics.median(list(values)))


def quantile(values: list[float], q: float) -> float:
    if not values:
        raise ValueError("quantile of an empty list")
    ordered = sorted(values)
    if len(ordered) == 1:
        return ordered[0]
    position = (len(ordered) - 1) * q
    low = int(math.floor(position))
    high = int(math.ceil(position))
    if low == high:
        return ordered[low]
    part = position - low
    return ordered[low] * (1.0 - part) + ordered[high] * part


def robust_scale(values: list[float], floor: float) -> float:
    center = median(values)
    mad = median(abs(value - center) for value in values)
    return max(floor, 1.4826 * mad)


def cv(values: list[float]) -> float | None:
    if len(values) < 2:
        return None
    mean = statistics.fmean(values)
    return statistics.pstdev(values) / abs(mean) if abs(mean) > 1e-12 else None


def finite_number(value: Any) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value)


def validate_event(event: Any, line: int, last_t: float) -> float:
    if not isinstance(event, dict):
        raise FormatError(f"line {line}: each line must be one JSON object")
    forbidden = {"text", "value", "content", "key", "device", "screen_width", "screen_height"}
    exposed = sorted(forbidden.intersection(event))
    if exposed:
        raise FormatError(f"line {line}: forbidden content/device field(s): {', '.join(exposed)}")
    t_ms = event.get("t_ms")
    if not finite_number(t_ms) or t_ms < 0 or t_ms < last_t:
        raise FormatError(f"line {line}: t_ms must be finite, nonnegative, and nondecreasing")
    kind = event.get("type")
    if kind == "pointer":
        if set(event) != {"t_ms", "type", "x", "y"}:
            raise FormatError(f"line {line}: pointer fields must be t_ms,type,x,y")
        x, y = event.get("x"), event.get("y")
        if not finite_number(x) or not finite_number(y) or not (0 <= x <= 1 and 0 <= y <= 1):
            raise FormatError(f"line {line}: pointer x/y must be fractions in [0,1]")
    elif kind == "click":
        if set(event) != {"t_ms", "type", "button"} or event.get("button") not in {"primary", "secondary", "middle"}:
            raise FormatError(f"line {line}: click needs only t_ms,type,button")
    elif kind == "text":
        allowed = {"t_ms", "type", "source", "op", "length", "correction", "strategy"}
        if not set(event).issubset(allowed) or not {"t_ms", "type", "source", "op", "length", "correction"}.issubset(event):
            raise FormatError(f"line {line}: text fields do not match FORMAT.md")
        if event.get("source") not in SOURCES or event.get("op") not in OPS:
            raise FormatError(f"line {line}: unknown text source or operation")
        length = event.get("length")
        if not isinstance(length, int) or isinstance(length, bool) or length < 1:
            raise FormatError(f"line {line}: text length must be a positive integer")
        if not isinstance(event.get("correction"), bool):
            raise FormatError(f"line {line}: correction must be boolean")
        strategy = event.get("strategy", "none")
        if strategy not in STRATEGIES:
            raise FormatError(f"line {line}: unknown correction strategy")
        if not event["correction"] and strategy != "none":
            raise FormatError(f"line {line}: a non-correction must use strategy=none")
    else:
        raise FormatError(f"line {line}: type must be pointer, click, or text")
    return float(t_ms)


def read_recording(path: Path) -> list[dict[str, Any]]:
    events: list[dict[str, Any]] = []
    last_t = -1.0
    for line_number, raw in enumerate(path.read_text(encoding="utf-8").splitlines(), 1):
        if not raw.strip():
            continue
        try:
            event = json.loads(raw)
        except json.JSONDecodeError as exc:
            raise FormatError(f"{path}:{line_number}: {exc.msg}") from exc
        last_t = validate_event(event, line_number, last_t)
        events.append(event)
    if not events:
        raise FormatError(f"{path}: recording is empty")
    return events


def write_recording(path: Path, events: list[dict[str, Any]]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text("".join(json.dumps(event, separators=(",", ":")) + "\n" for event in events), encoding="utf-8")


def local_peaks(values: list[float]) -> list[float]:
    if len(values) < 3:
        return []
    peak = max(values, default=0.0)
    cutoff = peak * 0.22
    return [values[i] for i in range(1, len(values) - 1) if values[i] >= cutoff and values[i] > values[i - 1] and values[i] >= values[i
